// REQ-ADV-002: the cases of contracts/race-advice.vectors.json (generated by scripts/gen-advice-vectors.ts). Plain data in,
// the advice out; the C# mirror (Muchi.Client RaceAdvice) is checked against the same file.
import defaultRuleset from '../../../contracts/ruleset-params.default.json';
import { DISTANCE_RULESET_KEYS, OPTIONAL_RULESET_KEYS, SKILL_RULESET_KEYS } from './ruleset.js';
import {
  adviceRules, computeRaceAdvice, type AdviceCourse, type AdviceField, type AdviceHorse, type AdviceInput, type AdviceMode, type AdviceRules,
} from './raceAdvice.js';

const RULES = adviceRules(defaultRuleset as Record<string, unknown>);
/** An old ruleset without the ground, distance and skill groups: style bias by distance, no going effects, skills ignored. */
const LEGACY_RULES = adviceRules(Object.fromEntries(Object.entries(defaultRuleset).filter(([k]) => ![...OPTIONAL_RULESET_KEYS, ...DISTANCE_RULESET_KEYS, ...SKILL_RULESET_KEYS].includes(k))));

const course = (trackId: string, surface: 'turf' | 'dirt', distanceM: number, going: AdviceCourse['going'], night = false, corners = 2, finalStraightM = 500): AdviceCourse =>
  ({ trackId, surface, distanceM, going, night, corners, finalStraightM });
const KIRAMEKI = course('kirameki_turf_2000', 'turf', 2000, 'good');
const BELLMOOR = course('bellmoor_turf_1200', 'turf', 1200, 'firm', false, 0, 1200);
const MINATO_DIRT_SLOPPY_NIGHT = course('minato_dirt_1800', 'dirt', 1800, 'sloppy', true, 2, 350);
const MINATO_TURF_SOFT = course('minato_turf_2400', 'turf', 2400, 'soft', false, 2, 600);
const AOBA_DIRT = course('aoba_dirt_1400', 'dirt', 1400, 'fast', false, 1, 500);

const horse = (id: string, name: string, style: AdviceHorse['style'], surface: AdviceHorse['surface'], distMinM: number, distMaxM: number, stats: [number, number, number, number, number], goingAptitude: AdviceHorse['goingAptitude'] = 'any', skill: AdviceHorse['skill'] = null): AdviceHorse =>
  ({ id, name, style, distMinM, distMaxM, surface, goingAptitude, speed: stats[0], stamina: stats[1], burst: stats[2], guts: stats[3], temper: stats[4], skill });
const AKATSUKI = horse('h1', 'シンセイアカツキ', 'sashi', 'turf', 1600, 2400, [740, 700, 760, 670, 520], 'any', { id: 'sk_kireaji', name: '切れ味鋭く', trigger: 'spurtBehind' });
const GINGA = horse('h2', 'ギンガノカナタ', 'senko', 'turf', 1800, 2600, [740, 820, 700, 840, 600], 'heavy', { id: 'sk_oudou', name: '王道の構え', trigger: 'finalStraight' });
const KOHAKU = horse('h3', 'コハクノヒカリ', 'nige', 'turf', 1400, 2000, [800, 600, 700, 680, 380], 'fast', { id: 'sk_shippu', name: '疾風の先駆け', trigger: 'leading' });
const HANABI = horse('h4', 'ハナビシャトル', 'senko', 'both', 1200, 1800, [660, 600, 640, 650, 620], 'any', { id: 'sk_uchirachi', name: '内ラチの申し子', trigger: 'cornerRail' });
const SUNA = horse('h5', 'スナアラシ', 'nige', 'dirt', 1200, 1800, [700, 640, 600, 740, 470], 'heavy', { id: 'sk_kagefumase', name: '影踏ませず', trigger: 'leading' });
const AOZORA = horse('h6', 'アオゾラマーチ', 'nige', 'turf', 1200, 1800, [600, 500, 560, 610, 480], 'fast', { id: 'sk_ichibanyari', name: '一番槍', trigger: 'goodStart' });
const TWIN_A = horse('h7', 'ミドリカワ', 'sashi', 'turf', 1600, 2400, [600, 600, 600, 600, 600]);
const TWIN_B = horse('h8', 'ミドリヤマ', 'sashi', 'turf', 1600, 2400, [600, 600, 600, 600, 600]);
const PLAIN = horse('h9', 'アイボウ', 'oikomi', 'turf', 1600, 2400, [700, 600, 700, 700, 620]);

const field = (nige: number, senko: number, sashi: number, oikomi: number, unknown: number): AdviceField => ({ nige, senko, sashi, oikomi, unknown });

function input(mode: AdviceMode, courses: AdviceCourse[], horses: AdviceHorse[], o: Partial<Pick<AdviceInput, 'field' | 'statCap' | 'fixedStats' | 'focusHorseId'>> & { rules?: AdviceRules } = {}): AdviceInput {
  return { v: 1, mode, courses, horses, field: o.field ?? null, rules: o.rules ?? RULES, statCap: o.statCap ?? null, fixedStats: o.fixedStats ?? false, focusHorseId: o.focusHorseId ?? null };
}

export const ADVICE_VECTOR_INPUTS: { name: string; input: AdviceInput }[] = [
  { name: 'friend kirameki good: equal fit so stats decide, out-of-range horse is poor', input: input('friend', [KIRAMEKI], [AKATSUKI, KOHAKU, HANABI], { field: field(1, 0, 2, 0, 0) }) },
  { name: 'friend bellmoor straight firm: corner skill cannot fire, fast-ground horse likes firm', input: input('friend', [BELLMOOR], [HANABI, AOZORA, AKATSUKI], { field: field(0, 1, 1, 1, 0) }) },
  { name: 'event dirt sloppy night: heavy-ground dirt horse, turf horses out of surface', input: input('event', [MINATO_DIRT_SLOPPY_NIGHT], [SUNA, GINGA, HANABI], { statCap: 3200 }) },
  { name: 'friend minato soft 2400: stamina matters, low-temper focus horse', input: input('friend', [MINATO_TURF_SOFT], [GINGA, AKATSUKI, KOHAKU], { focusHorseId: 'h3', field: field(3, 1, 0, 0, 0) }) },
  { name: 'challenge: statCap, skills off, CPU field unknown', input: input('challenge', [AOBA_DIRT], [HANABI, SUNA], { statCap: 3200, field: field(0, 0, 0, 0, 7) }) },
  { name: 'timeattack: no field, skills off', input: input('timeattack', [KIRAMEKI], [AKATSUKI], { statCap: 3200, field: field(0, 0, 0, 0, 0) }) },
  { name: 'ranked pool of five courses: counts, not chances', input: input('ranked', [KIRAMEKI, BELLMOOR, MINATO_DIRT_SLOPPY_NIGHT, MINATO_TURF_SOFT, AOBA_DIRT], [AKATSUKI, HANABI, SUNA], { statCap: 3000 }) },
  { name: 'even: identical horses tie', input: input('friend', [KIRAMEKI], [TWIN_B, TWIN_A]) },
  { name: 'stats break the tie under the cap', input: input('ranked', [KIRAMEKI], [TWIN_A, PLAIN], { statCap: 3200 }) },
  { name: 'stats tie when both exceed the cap', input: input('ranked', [KIRAMEKI], [GINGA, PLAIN], { statCap: 3000 }) },
  { name: 'fixed stats event: only aptitude', input: input('event', [AOBA_DIRT], [HANABI, AKATSUKI], { fixedStats: true }) },
  { name: 'nige alone: no other front-runner, goodStart skill tip', input: input('friend', [BELLMOOR], [AOZORA], { field: field(0, 2, 1, 1, 0) }) },
  { name: 'legacy 1.1 ruleset: distance bias, no skills, no ground keys', input: input('friend', [BELLMOOR], [AOZORA, AKATSUKI], { rules: LEGACY_RULES }) },
  { name: 'legacy 1.1 ruleset long race', input: input('friend', [MINATO_TURF_SOFT], [GINGA], { rules: LEGACY_RULES }) },
  { name: 'no horses', input: input('friend', [KIRAMEKI], []) },
  { name: 'tutorial: fixed', input: input('tutorial', [course('aoba_turf_1600', 'turf', 1600, 'good', false, 1, 650)], [PLAIN]) },
];

export function adviceVectorsJson(): string {
  const cases = ADVICE_VECTOR_INPUTS.map((c) => ({ name: c.name, input: c.input, output: computeRaceAdvice(c.input) }));
  return JSON.stringify({ _note: 'Generated by server/scripts/gen-advice-vectors.ts (npm run gen:advice-vectors). The server (raceAdvice.ts) and Muchi.Client RaceAdvice must both map every input to its output. Do not edit.', v: 1, cases }, null, 1) + '\n';
}
